/* Synthetic GPU checks consume shaders generated by test_rsx_framebuffer_srgb.
 * Float observation targets keep RT quantization from hiding transfer errors. */
#include "../rsx_metal_backend.m"
u8* vm_base;
u32 cellGcmResolveLocated(int local, u32 off) { (void)local; return off; }
static unsigned checks, failures;
#define CHECK(v,label) do { ++checks; if (!(v)) { ++failures; fprintf(stderr,"FAIL %s\n",label); } } while(0)
static float encode(float v)
{
    if (v < 0.0031308f) return fminf(1, fmaxf(0, v * 12.92f));
    return fminf(1, fmaxf(0, 1.055f * powf(v, 1.f/2.4f) - .055f));
}
int main(int argc, char** argv)
{
    if (argc != 2) return 2;
    @autoreleasepool {
        s_dev = MTLCreateSystemDefaultDevice(); if (!s_dev) return 2;
        s_queue = [s_dev newCommandQueue]; NSError* err = nil;
        const char* vs = "#include <metal_stdlib>\nusing namespace metal;struct V{float4 p[[position]];float4 c[[user(locn0)]];};vertex V vs(uint i[[vertex_id]],constant float4& c[[buffer(0)]]){float2 p[3]={float2(-1,-1),float2(3,-1),float2(-1,3)};return{float4(p[i],0,1),c};}";
        id<MTLLibrary> vl = [s_dev newLibraryWithSource:[NSString stringWithUTF8String:vs] options:nil error:&err];
        CHECK(vl != nil, "synthetic varying vertex shader"); if (!vl) return 2;
        const char* filenames[] = {"active-packer.ps.hlsl", "mrt-packer.ps.hlsl", "raw-packer.ps.hlsl"};
        for (unsigned mode=0; mode<3; ++mode) {
            char path[1024]; snprintf(path,sizeof path,"%s/%s",argv[1],filenames[mode]);
            FILE* f=fopen(path,"rb"); if (!f) return 2; fseek(f,0,SEEK_END); long len=ftell(f); rewind(f);
            char* source=calloc(1,(size_t)len+1); if (!source) return 2; fread(source,1,(size_t)len,f); fclose(f);
            id<MTLFunction> fp=eng_function(source,RSX_SHADER_STAGE_FRAGMENT,"synthetic packer"); free(source);
            CHECK(fp != nil,"generated HLSL translates and compiles"); if (!fp) return 2;
            const unsigned targets=mode==1?4:1;
            MTLRenderPipelineDescriptor* pd=[MTLRenderPipelineDescriptor new];
            pd.vertexFunction=[vl newFunctionWithName:@"vs"]; pd.fragmentFunction=fp;
            id<MTLTexture> out[4];
            for(unsigned t=0;t<targets;++t) {
                pd.colorAttachments[t].pixelFormat=MTLPixelFormatRGBA32Float;
                MTLTextureDescriptor* td=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA32Float width:1 height:1 mipmapped:NO];
                td.usage=MTLTextureUsageRenderTarget;td.storageMode=MTLStorageModeShared;out[t]=[s_dev newTextureWithDescriptor:td];
            }
            id<MTLRenderPipelineState> pipeline=[s_dev newRenderPipelineStateWithDescriptor:pd error:&err];
            CHECK(pipeline!=nil,"float observation pipeline");if(!pipeline)return 2;
            const float levels[]={0,.0005f,.003f,.0031308f,.004f,.02f,.05f,.1f,.25f,.5f,.75f,1};
            for(unsigned k=0;k<48;++k) {
                float values[4]={levels[k%12],levels[(k*5+3)%12],levels[(k*7+1)%12],(float)(k%9)/8};
                MTLRenderPassDescriptor* rp=[MTLRenderPassDescriptor renderPassDescriptor];
                for(unsigned t=0;t<targets;++t){rp.colorAttachments[t].texture=out[t];rp.colorAttachments[t].loadAction=MTLLoadActionClear;rp.colorAttachments[t].storeAction=MTLStoreActionStore;}
                id<MTLCommandBuffer> cb=[s_queue commandBuffer];id<MTLRenderCommandEncoder> e=[cb renderCommandEncoderWithDescriptor:rp];
                [e setRenderPipelineState:pipeline];[e setVertexBytes:values length:16 atIndex:0];[e drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:3];[e endEncoding];[cb commit];[cb waitUntilCompleted];
                CHECK(cb.status==MTLCommandBufferStatusCompleted&&!cb.error,"GPU completes");
                for(unsigned t=0;t<targets;++t){float got[4];[out[t]getBytes:got bytesPerRow:16 fromRegion:MTLRegionMake2D(0,0,1,1)mipmapLevel:0];
                    for(unsigned c=0;c<4;++c){const float input=values[c==3?3:((c+t)%4)];const float expected=c==3||mode==2?input:encode(input);CHECK(fabsf(got[c]-expected)<2e-6f,"RGB piecewise transfer, asymmetric MRT and alpha");}}
            }
        }
        printf("framebuffer sRGB GPU: %u checks/%u failures\n",checks,failures);return failures?1:0;
    }
}
